  "kp-m2-p1-c4-la-ge-lang-ri-cheng-shu-fa": {"anchor":"∇f=λ∇g；H=fₓₓfᵧᵧ−fₓᵧ²","keyPoints":["驻点是必要候选，不是结论","二阶判别要看 Hessian 行列式和主元","约束极值必须同时满足约束方程"],"example":"在 x²+y²=1 上求 xy 的极值，可令 ∇(xy)=λ∇(x²+y²)。"},
  "kp-m2-p1-c4-zui-da-zhi-zui-xiao-zhi-ying-yong": {"anchor":"∇f=λ∇g；H=fₓₓfᵧᵧ−fₓᵧ²","keyPoints":["驻点是必要候选，不是结论","二阶判别要看 Hessian 行列式和主元","约束极值必须同时满足约束方程"],"example":"在 x²+y²=1 上求 xy 的极值，可令 ∇(xy)=λ∇(x²+y²)。"},
  "kp-m2-p1-c5-ding-yi": {"anchor":"∬ᴰf(x,y)dA=∫ₐᵇ∫_{φ₁(x)}^{φ₂(x)}f(x,y)dydx","keyPoints":["X 型区域先写 y 的上下限","Y 型区域先写 x 的左右限","交换次序前要重新画边界"],"example":"对三角形 0≤x≤1，0≤y≤x，先对 y 积分最直接。"},
  "kp-m2-p1-c5-ji-he-yi-yi": {"anchor":"y−f(x₀)=f′(x₀)(x−x₀)","keyPoints":["f′>0 表示局部向右上升","f′<0 表示局部向右下降","f′=0 只表示切线水平"],"example":"y=x² 在 (1,1) 的切线为 y−1=2(x−1)，法线斜率为 −1/2。"},
  "kp-m2-p1-c5-ji-ben-xing-zhi": {"anchor":"∬ᴰf(x,y)dA=∫ₐᵇ∫_{φ₁(x)}^{φ₂(x)}f(x,y)dydx","keyPoints":["X 型区域先写 y 的上下限","Y 型区域先写 x 的左右限","交换次序前要重新画边界"],"example":"对三角形 0≤x≤1，0≤y≤x，先对 y 积分最直接。"},
  "kp-m2-p1-c5-x-xing-qu-yu": {"anchor":"∬ᴰf(x,y)dA=∫ₐᵇ∫_{φ₁(x)}^{φ₂(x)}f(x,y)dydx","keyPoints":["X 型区域先写 y 的上下限","Y 型区域先写 x 的左右限","交换次序前要重新画边界"],"example":"对三角形 0≤x≤1，0≤y≤x，先对 y 积分最直接。"},
  "kp-m2-p1-c5-y-xing-qu-yu": {"anchor":"∬ᴰf(x,y)dA=∫ₐᵇ∫_{φ₁(x)}^{φ₂(x)}f(x,y)dydx","keyPoints":["X 型区域先写 y 的上下限","Y 型区域先写 x 的左右限","交换次序前要重新画边界"],"example":"对三角形 0≤x≤1，0≤y≤x，先对 y 积分最直接。"},
  "kp-m2-p1-c5-xian-x-hou-y": {"anchor":"∬ᴰf(x,y)dA=∫ₐᵇ∫_{φ₁(x)}^{φ₂(x)}f(x,y)dydx","keyPoints":["X 型区域先写 y 的上下限","Y 型区域先写 x 的左右限","交换次序前要重新画边界"],"example":"对三角形 0≤x≤1，0≤y≤x，先对 y 积分最直接。"},
  "kp-m2-p1-c5-xian-y-hou-x": {"anchor":"∬ᴰf(x,y)dA=∫ₐᵇ∫_{φ₁(x)}^{φ₂(x)}f(x,y)dydx","keyPoints":["X 型区域先写 y 的上下限","Y 型区域先写 x 的左右限","交换次序前要重新画边界"],"example":"对三角形 0≤x≤1，0≤y≤x，先对 y 积分最直接。"},
  "kp-m2-p1-c5-jiao-huan-ji-fen-ci-xu": {"anchor":"∬ᴰf(x,y)dA=∫ₐᵇ∫_{φ₁(x)}^{φ₂(x)}f(x,y)dydx","keyPoints":["X 型区域先写 y 的上下限","Y 型区域先写 x 的左右限","交换次序前要重新画边界"],"example":"对三角形 0≤x≤1，0≤y≤x，先对 y 积分最直接。"},
  "kp-m2-p1-c5-fen-qu-yu": {"anchor":"∬ᴰf(x,y)dA=∫ₐᵇ∫_{φ₁(x)}^{φ₂(x)}f(x,y)dydx","keyPoints":["X 型区域先写 y 的上下限","Y 型区域先写 x 的左右限","交换次序前要重新画边界"],"example":"对三角形 0≤x≤1，0≤y≤x，先对 y 积分最直接。"},
  "kp-m2-p1-c5-x-r-cos": {"anchor":"x=r cosθ，y=r sinθ，dA=r dr dθ","keyPoints":["x=r cosθ，y=r sinθ","dA=r dr dθ","先画角度范围，再写半径范围"],"example":"半径 R 的圆面积为 ∫₀²π∫₀ᴿr drdθ=πR²。"},
  "kp-m2-p1-c5-y-r-sin": {"anchor":"x=r cosθ，y=r sinθ，dA=r dr dθ","keyPoints":["x=r cosθ，y=r sinθ","dA=r dr dθ","先画角度范围，再写半径范围"],"example":"半径 R 的圆面积为 ∫₀²π∫₀ᴿr drdθ=πR²。"},
  "kp-m2-p1-c5-da-r-dr-d": {"anchor":"x=r cosθ，y=r sinθ，dA=r dr dθ","keyPoints":["x=r cosθ，y=r sinθ","dA=r dr dθ","先画角度范围，再写半径范围"],"example":"半径 R 的圆面积为 ∫₀²π∫₀ᴿr drdθ=πR²。"},
  "kp-m2-p1-c5-yuan-xing-huan-xing-shan-xing-qu-yu": {"anchor":"x=r cosθ，y=r sinθ，dA=r dr dθ","keyPoints":["x=r cosθ，y=r sinθ","dA=r dr dθ","先画角度范围，再写半径范围"],"example":"半径 R 的圆面积为 ∫₀²π∫₀ᴿr drdθ=πR²。"},
  "kp-m2-p1-c5-dui-chen-xing": {"anchor":"∬ᴰf(x,y)dA=∫ₐᵇ∫_{φ₁(x)}^{φ₂(x)}f(x,y)dydx","keyPoints":["X 型区域先写 y 的上下限","Y 型区域先写 x 的左右限","交换次序前要重新画边界"],"example":"对三角形 0≤x≤1，0≤y≤x，先对 y 积分最直接。"},
  "kp-m2-p1-c5-ji-ou-xing": {"anchor":"偶：f(−x)=f(x)；奇：f(−x)=−f(x)","keyPoints":["偶函数满足 f(−x)=f(x)","奇函数满足 f(−x)=−f(x)","奇函数在 0 有定义时必有 f(0)=0"],"example":"x² 是偶函数，x³ 是奇函数；sin x 为奇函数，cos x 为偶函数。"},
  "kp-m2-p1-c5-qu-yu-chai-fen": {"anchor":"∬ᴰf(x,y)dA=∫ₐᵇ∫_{φ₁(x)}^{φ₂(x)}f(x,y)dydx","keyPoints":["X 型区域先写 y 的上下限","Y 型区域先写 x 的左右限","交换次序前要重新画边界"],"example":"对三角形 0≤x≤1，0≤y≤x，先对 y 积分最直接。"},
  "kp-m2-p1-c5-zuo-biao-xi-xuan-ze": {"anchor":"∬ᴰf(x,y)dA=∫ₐᵇ∫_{φ₁(x)}^{φ₂(x)}f(x,y)dydx","keyPoints":["X 型区域先写 y 的上下限","Y 型区域先写 x 的左右限","交换次序前要重新画边界"],"example":"对三角形 0≤x≤1，0≤y≤x，先对 y 积分最直接。"},
  "kp-m2-p1-c5-ti-ji": {"anchor":"∬ᴰf(x,y)dA=∫ₐᵇ∫_{φ₁(x)}^{φ₂(x)}f(x,y)dydx","keyPoints":["X 型区域先写 y 的上下限","Y 型区域先写 x 的左右限","交换次序前要重新画边界"],"example":"对三角形 0≤x≤1，0≤y≤x，先对 y 积分最直接。"},
  "kp-m2-p1-c5-ping-mian-bao-pian-zhi-liang": {"anchor":"n·[(x,y,z)−(x₀,y₀,z₀)]=0","keyPoints":["一般式 Ax+By+Cz+D=0 的法向量是 (A,B,C)","同一平面方程整体乘非零常数不变","写方程必须同时有一个平面点和一个法向方向"],"example":"过点 (1,0,0)、法向量 (2,−1,3) 的平面为 2(x−1)−y+3z=0。"},
